gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    TransferData *transfer_data = (TransferData *)data;
    Transfer *transfer = transfer_data->transfer;
    Connection *connection = transfer_data->connection;
    Buddy *buddy = connection_find_buddy(connection, transfer_data->buddy_handle);

    if (!buddy || !transfer_start(transfer, buddy, fd)) {
        return FALSE;
    }

    // Setup transfer callbacks
    transfer_set_read_callback(transfer, read_callback);
    transfer_set_write_callback(transfer, write_callback);
    transfer_set_complete_callback(transfer, transfer_complete);

    // Associate transfer data with the transfer object
    transfer_set_data(transfer, transfer_data);

    return TRUE;
}

gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    Transfer *transfer = (Transfer *)data;
    Connection *conn = transfer_get_connection(transfer);
    Buddy *buddy = connection_get_buddy(conn);

    if (!buddy || !transfer_start(transfer, buddy)) {
        return FALSE;
    }

    transfer_set_fd(transfer, fd);
    transfer_set_condition(transfer, cond);

    g_signal_connect(transfer, "data-received", G_CALLBACK(on_data_received), NULL);
    g_signal_connect(transfer, "transfer-complete", G_CALLBACK(on_transfer_complete), NULL);

    return TRUE;
}

gboolean handle_file_transfer_initiation(gpointer data, gint fd, b_input_condition cond) {
    gpointer transfer_data = data;
    gpointer transfer_object = get_transfer_object(transfer_data);
    gpointer connection = get_connection_from_transfer(transfer_object);

    if (!transfer_object || !connection) {
        return FALSE;
    }

    gpointer buddy = get_buddy_from_connection(connection);

    if (!buddy) {
        return FALSE;
    }

    if (!start_file_transfer(transfer_object, buddy)) {
        return FALSE;
    }

    setup_transfer_callbacks(transfer_object);
    associate_transfer_data_with_object(transfer_object, transfer_data);

    return TRUE;
}

gboolean handle_file_transfer_initiation(gpointer data, gint fd, b_input_condition cond) {
    Transfer *transfer = (Transfer *)data;
    Connection *connection = transfer->connection;
    Buddy *buddy = connection->buddy;

    if (!transfer || !connection || !buddy) {
        return FALSE;
    }

    if (!start_file_transfer(transfer, fd, buddy)) {
        return FALSE;
    }

    setup_transfer_callbacks(transfer);
    associate_transfer_data(transfer, data);

    return TRUE;
}

gboolean handle_new_file_transfer(gpointer data, gint fd, b_input_condition cond) {
    Transfer *transfer = (Transfer *)data;
    Connection *conn = transfer->connection;
    Buddy *buddy = find_buddy_by_id(conn, transfer->buddy_id);

    if (!buddy || !start_file_transfer(transfer)) {
        return FALSE;
    }

    setup_transfer_callbacks(transfer);
    associate_transfer_data(transfer, data);

    return TRUE;
}
